insert into wa.versions(name,config) values('municipal-v1','{"texts":{"controls":"Escolha uma das opções abaixo.","welcome":"Olá! Este é o atendimento de {municipio}. Como podemos ajudar?\nEscolha um botão ou digite o número da opção.","multi_hint":"Digite os números separados por vírgula. Exemplo: 1, 3.","zero_hint":"Digite 0 para nenhuma opção.","photo_received":"Foto recebida em armazenamento privado","review":"Confira suas informações antes de concluir:\n\n{resumo}\nEstá tudo correto?","done":"Registro concluído. Protocolo: {protocolo}","simulated":"Simulação concluída. Nenhum cadastro real foi alterado e nenhuma mensagem foi enviada.","completed":{"colaborador":"Cadastro de colaborador registrado. A equipe municipal poderá conferir suas informações. Protocolo: {protocolo}","relato":"Relato registrado e encaminhado para triagem municipal. Este registro não substitui os telefones de emergência. Protocolo: {protocolo}","solicitacao":"Solicitação registrada e aguardando triagem municipal. O registro não garante atendimento imediato. Protocolo: {protocolo}"}},"buttons":{"optional":[{"action":"skip","label":"Pular esta pergunta"}],"review":[{"action":"confirm","label":"Confirmar e concluir"},{"action":"correct","label":"Corrigir respostas"},{"action":"restart","label":"Voltar ao início"}],"done":[{"action":"restart","label":"Voltar ao início"}]},"errors":{"required":"Esta resposta é obrigatória.","too_long":"A resposta é muito longa. Envie até 2.000 caracteres.","phone":"Informe um telefone com DDD, entre 10 e 15 dígitos.","integer":"Informe um número inteiro não negativo, com até 7 dígitos.","choice":"Escolha somente uma opção da lista pelos números apresentados.","multi":"Digite somente os números da lista, separados por vírgula. Use 0 sozinho apenas nas perguntas opcionais.","exclusive":"NÃO HÁ não pode ser combinado com outras opções.","photo":"Envie uma foto JPEG ou PNG de até 5 MB, ou use o botão para pular.","stale":"Esse botão pertence a outra etapa. Use as opções atuais abaixo.","menu":"Escolha uma das opções do atendimento.","review":"Use um dos botões para confirmar ou corrigir suas respostas.","done":"Seu registro já foi concluído. Use o botão para voltar ao início.","offer_required":"Informe ao menos uma ajuda, equipamento, material ou apoio que pode oferecer.","invalid":"Não foi possível interpretar a resposta. Confira a pergunta abaixo."}}'::jsonb) returning id into v;
